// === Tab: mySketch ===
function setup() {
  createCanvas(1648, 934);
}

function draw() {
  background(255);

  let curveWidth = 10.0;
  let curveThickness = 10.0;
  let angleOffset = 0.2;

  let angleIncrement = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0.0, 0.2);
  let angleA = 0.0;
  let angleB = angleA + angleOffset;

  let k = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 2.0, 4.0);

  for (i = 0; i < height; i += curveWidth*k) {
    let waveColor = map(i, 0, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))+10, 0, 255);
    noStroke();

    pushMatrix();
    translate(0, 400);
    fill(waveColor);
    beginShape(QUAD_STRIP);
    for (x = 0; x <= width; x += 10) {
      //let y1 = i + (sin(angleA)* curveWidth);
      //let y2 = i + (sin(angleB)* curveWidth);
      let y1 = i + (sin(angleB) * curveWidth);
      let y2 = i + (cos(angleA) * curveWidth);
      vertex(x, y1);
      vertex(x, y2 + curveThickness);
      angleA += angleIncrement;
      angleB = angleA + angleOffset;
    }
    endShape();

    pushMatrix();
    scale(1.0, -1.0);
    beginShape(QUAD_STRIP);
    for (x = 0; x <= width; x += 10) {
      //let y1 = i + (sin(angleA)* curveWidth);
      //let y2 = i + (sin(angleB)* curveWidth);
      var y1 = i + (sin(angleB) * curveWidth);
      var y2 = i + (cos(angleA) * curveWidth);
      vertex(x, y1);
      vertex(x, y2 + curveThickness);
      angleA += angleIncrement;
      angleB = angleA + angleOffset;
    }
    endShape();
    popMatrix();
    popMatrix();
  }
}

